using NuevoAvatar.Periodo.Nuevo.Entities;using NuevoAvatar.Periodo.Nuevo.Repository;using NuevoAvatar.Periodo.Nuevo.Services;using Xunit;
public class PeriodoReglasTest{
[Fact]public void EstadoSeDerivaDeFechas(){var hoy=DateTime.Today;Assert.Equal("ACTIVO",new PeriodoRequest{FechaInicio=hoy,FechaFin=hoy}.Estado);Assert.Equal("FUTURO",new PeriodoRequest{FechaInicio=hoy.AddDays(1),FechaFin=hoy.AddDays(2)}.Estado);Assert.Equal("CERRADO",new PeriodoRequest{FechaInicio=hoy.AddDays(-2),FechaFin=hoy.AddDays(-1)}.Estado);}
[Fact]public async Task DuplicadoProduceConflicto(){var repo=new Repo{Duplicado=true};var s=new PeriodoService(repo,new PeriodoValidator());await Assert.ThrowsAsync<PeriodoConflictoException>(()=>s.CrearAsync(new PeriodoRequest{Anio=2026,NumeroPeriodo=1,FechaInicio=new(2026,1,1),FechaFin=new(2026,2,1)}));}
sealed class Repo:IPeriodoRepository{public bool Duplicado;public Task<bool> ExisteDuplicadoAsync(short a,byte n,int?e=null)=>Task.FromResult(Duplicado);public Task<bool> ExisteSolapamientoAsync(short a,DateTime i,DateTime f,int?e=null)=>Task.FromResult(false);public Task<IEnumerable<PeriodoRequest>> ObtenerTodosAsync()=>Task.FromResult<IEnumerable<PeriodoRequest>>([]);public Task<PeriodoRequest?> ObtenerPorIdAsync(int id)=>Task.FromResult<PeriodoRequest?>(null);public Task<int> CrearAsync(PeriodoRequest r)=>Task.FromResult(1);public Task<bool> ModificarAsync(int id,PeriodoRequest r)=>Task.FromResult(true);public Task<bool> EliminarAsync(int id)=>Task.FromResult(true);}}
